// План specs/admin-access.md, 3.2 (кейс AA-07). Пользователь «בדיקה». Только чтение. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage } from '../admin-plans/plans-helpers';
import { DASHBOARD_URL, expectNoAdminPanel } from './access-helpers';

test.use({ storageState: '../auth/user.json' });

test.describe('Admin Panel — доступ обычного пользователя (#12126fac)', () => {
  test('/adminpanel URL variants (trailing slash, ?tab=plans, other case, #funnel) all redirect to the dashboard #12126fac @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');

    for (const path of ['/adminpanel/', '/adminpanel?tab=plans', '/AdminPanel', '/adminpanel#funnel']) {
      await test.step(path, async () => {
        await page.goto(path);
        await expect(page).toHaveURL(DASHBOARD_URL);
        await expectNoAdminPanel(page);
      });
    }
  });
});
